def main():
    import sys
    input = sys.stdin.read
    X = int(input().strip())

    def years_to_reach_balance(X):
        low, high = 0, 10**18
        while low < high:
            mid = (low + high) // 2
            balance = 100 * (1.01 ** mid)
            if balance >= X:
                high = mid
            else:
                low = mid + 1
        return low

    result = years_to_reach_balance(X)
    print(result)

if __name__ == "__main__":
    main()
